import type { L10n } from '@/lib/types';

export type FrameShapeKey = 'rectangle' | 'square' | 'round' | 'oval' | 'panto' | 'aviator' | 'cat-eye' | 'geometric' | 'browline' | 'wrap';

export interface FrameRow {
  slug: string;
  sku: string;
  kind: 'optical' | 'sun';
  brand: string | null;
  model: string | null;
  shape: FrameShapeKey;
  material: 'acetate' | 'metal' | 'mixed';
  colour: L10n;
  /** swatch colour of the frame */
  hex: string;
  /** sun lens tint (null for optical frames) */
  lens: L10n | null;
  audience: 'men' | 'women' | 'unisex' | 'kids';
  /** optical frame sold with a magnetic sun clip-on */
  clip: boolean;
  /** marked "Polarized" on the lens or temple */
  polarised: boolean;
  /** marked titanium on the frame or demo lens */
  titanium: boolean;
  price: number;
  priceFromTag: boolean;
  images: number;
  /** shoot date */
  shot: string;
}

